import { useEffect, useState } from "react";

type Post = { slug: string; title: string; date: string; dateLabel: string; img: string; alt: string; url: string };

// Reads public/blog/posts.json (generated by scripts/build-blog.mjs). Links are plain <a> — /blog/ is static, not a router route.
const CSS = `.hme .lp{padding:48px 0 8px}.hme .lp-hd{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:20px}.hme .lp-hd h2{font-size:36px;line-height:1.1;margin:6px 0 0}.hme .lp-all{color:var(--teal);font-weight:800;text-decoration:none}.hme .lp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:24px}.hme .lp-card{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;text-decoration:none;color:var(--ink)}.hme .lp-card img{width:100%;height:auto;aspect-ratio:1200/627;object-fit:cover;display:block}.hme .lp-card div{padding:18px 22px 22px}.hme .lp-card time{color:var(--teal);font-weight:800;font-size:12px;letter-spacing:.08em;text-transform:uppercase}.hme .lp-card h3{margin:6px 0 0;font-size:21px;line-height:1.3;font-weight:800}@media(max-width:760px){.hme .lp-hd h2{font-size:28px}}`;

const LatestPosts = () => {
  const [posts, setPosts] = useState<Post[]>([]);
  useEffect(() => {
    let live = true;
    fetch("/blog/posts.json").then(r => (r.ok ? r.json() : [])).then(d => { if (live && Array.isArray(d)) setPosts(d.slice(0, 2)); }).catch(() => {});
    return () => { live = false; };
  }, []);
  if (!posts.length) return null;
  return (
    <section className="lp" aria-labelledby="lp-h">
      <style>{CSS}</style>
      <div className="lp-hd"><div><p className="eyebrow">Operator notes</p><h2 id="lp-h">Latest from the blog</h2></div><a className="lp-all" href="/blog/">All posts →</a></div>
      <div className="lp-grid">
        {posts.map(p => (
          <a className="lp-card" href={p.url} key={p.slug}>
            <img src={p.img} alt={p.alt} width={1200} height={627} loading="lazy" />
            <div><time dateTime={p.date}>{p.dateLabel}</time><h3>{p.title}</h3></div>
          </a>
        ))}
      </div>
    </section>
  );
};

export default LatestPosts;
